using System.Text;

namespace ApiGenerator;

/// <summary>
/// Plantillas de código. Todo lo generado es <c>partial</c> y termina en <c>.g.cs</c>:
/// la lógica a mano va en archivos hermanos sin <c>.g</c>, que el generador nunca toca.
/// </summary>
public static class Templates
{
    public const string Header =
        "// <auto-generated>\n" +
        "// Generado por tools/ApiGenerator a partir del modelo EF y entities.config.\n" +
        "// NO editar: los cambios se pierden al regenerar. Extender con un archivo partial sin \".g\".\n" +
        "// </auto-generated>\n" +
        "#nullable enable\n\n";

    // Alias para las entidades EF: los nombres de módulo (Items, Bancos, Entidades...) coinciden con
    // nombres de entidades y de namespaces, así que siempre se referencian como Db.X.
    private const string DbAlias = "using Db = global::API.DA.Entities;";

    public static string Models(EntitySpec e)
    {
        var sb = new StringBuilder(Header);
        sb.AppendLine("using System.ComponentModel.DataAnnotations;");
        sb.AppendLine("using API.SERVICE.Models.Common;");
        sb.AppendLine();
        sb.AppendLine($"namespace API.SERVICE.Models.{e.Module};");
        sb.AppendLine();

        // Display
        sb.AppendLine($"/// <summary>Salida de {e.TableName}.</summary>");
        sb.AppendLine($"public sealed partial class {e.S}Display");
        sb.AppendLine("{");
        foreach (var p in e.DisplayProps)
            sb.AppendLine($"    public {p.EntityTypeName} {p.Name} {{ get; init; }}{(p.IsString && !p.IsNullable ? " = string.Empty;" : "")}");
        sb.AppendLine("}");
        sb.AppendLine();

        // Dto
        if (e.CanCreate || e.CanUpdate)
        {
            sb.AppendLine($"/// <summary>Entrada de alta/modificación de {e.TableName}.</summary>");
            sb.AppendLine($"public sealed partial class {e.S}Dto");
            sb.AppendLine("{");
            foreach (var p in e.DtoProps)
            {
                if (e.Key == p)
                    sb.AppendLine("    /// <summary>Clave no autonumérica: obligatoria en el alta, se ignora en la modificación (va en la ruta).</summary>");
                var attrs = new List<string>();
                if (!p.IsNullable)
                    attrs.Add(p.IsString ? "Required(AllowEmptyStrings = true)" : "Required");
                if (p.IsString && p.MaxLength is > 0)
                    attrs.Add($"MaxLength({p.MaxLength})");
                if (attrs.Count > 0)
                    sb.AppendLine($"    [{string.Join(", ", attrs)}]");
                sb.AppendLine($"    public {p.NullableTypeName} {p.Name} {{ get; set; }}");
                sb.AppendLine();
            }
            TrimBlankLine(sb);
            sb.AppendLine("}");
            sb.AppendLine();
        }

        // Filter
        sb.AppendLine($"/// <summary>Filtros del listado de {e.TableName}.</summary>");
        sb.AppendLine($"public sealed partial class {e.S}Filter : PagedQuery");
        sb.AppendLine("{");
        if (e.SearchProps.Count > 0)
        {
            sb.AppendLine($"    /// <summary>Búsqueda parcial en {string.Join(", ", e.SearchProps.Select(p => p.Name))}.</summary>");
            sb.AppendLine("    [MaxLength(100)]");
            sb.AppendLine("    public string? Q { get; set; }");
            sb.AppendLine();
        }
        foreach (var p in e.IdFilterProps.Concat(e.FlagFilterProps))
        {
            sb.AppendLine($"    public {p.NullableTypeName} {p.Name} {{ get; set; }}");
            sb.AppendLine();
        }
        if (e.DateFilterProp is { } d)
        {
            sb.AppendLine($"    /// <summary>{d.Name} desde (inclusive).</summary>");
            sb.AppendLine($"    public {TypeNames.Of(d.Underlying)}? {d.Name}Desde {{ get; set; }}");
            sb.AppendLine();
            sb.AppendLine($"    /// <summary>{d.Name} hasta (inclusive, día completo).</summary>");
            sb.AppendLine($"    public {TypeNames.Of(d.Underlying)}? {d.Name}Hasta {{ get; set; }}");
            sb.AppendLine();
        }
        TrimBlankLine(sb);
        sb.AppendLine("}");
        return sb.ToString();
    }

    public static string Mappings(EntitySpec e)
    {
        var sb = new StringBuilder(Header);
        sb.AppendLine($"using API.SERVICE.Models.{e.Module};");
        sb.AppendLine(DbAlias);
        sb.AppendLine();
        sb.AppendLine($"namespace API.SERVICE.Mappings.{e.Module};");
        sb.AppendLine();
        sb.AppendLine($"public static partial class {e.S}Mappings");
        sb.AppendLine("{");
        sb.AppendLine($"    public static {e.S}Display ToDisplay(this Db.{e.EntityClass} entity) => new()");
        sb.AppendLine("    {");
        foreach (var p in e.DisplayProps)
            sb.AppendLine($"        {p.Name} = entity.{p.Name},");
        sb.AppendLine("    };");

        if (e.CanCreate || e.CanUpdate)
        {
            sb.AppendLine();
            sb.AppendLine($"    public static Db.{e.EntityClass} ToEntity(this {e.S}Dto dto)");
            sb.AppendLine("    {");
            sb.AppendLine($"        var entity = new Db.{e.EntityClass}();");
            if (e.DtoIncludesKey)
                sb.AppendLine($"        entity.{e.Key!.Name} = {Read(e.Key!, "dto")};");
            sb.AppendLine("        dto.ApplyTo(entity);");
            sb.AppendLine("        return entity;");
            sb.AppendLine("    }");
            sb.AppendLine();
            sb.AppendLine("    /// <summary>Copia el Dto sobre la entidad (no toca la clave).</summary>");
            sb.AppendLine($"    public static void ApplyTo(this {e.S}Dto dto, Db.{e.EntityClass} entity)");
            sb.AppendLine("    {");
            foreach (var p in e.DtoProps.Where(p => p != e.Key))
                sb.AppendLine($"        entity.{p.Name} = {Read(p, "dto")};");
            sb.AppendLine("    }");
        }

        sb.AppendLine("}");
        return sb.ToString();
    }

