    public static string Repository(EntitySpec e)
    {
        var sb = new StringBuilder(Header);
        sb.AppendLine("using API.DA.DbContexts;");
        sb.AppendLine($"using API.SERVICE.Interfaces.{e.Module};");
        sb.AppendLine($"using API.SERVICE.Models.{e.Module};");
        sb.AppendLine("using API.SERVICE.Repositories.Base;");
        sb.AppendLine(DbAlias);
        sb.AppendLine();
        sb.AppendLine($"namespace API.SERVICE.Repositories.{e.Module};");
        sb.AppendLine();
        var baseClass = e.HasKey
            ? $"EfRepository<Db.{e.EntityClass}, {e.KeyType}, {e.S}Filter>"
            : $"EfQueryRepository<Db.{e.EntityClass}, {e.S}Filter>";
        sb.AppendLine($"public sealed partial class {e.S}Repository : {baseClass}, I{e.S}Repository");
        sb.AppendLine("{");
        sb.AppendLine($"    public {e.S}Repository(ElRenacerDbContext context) : base(context) {{ }}");
        sb.AppendLine();
        sb.AppendLine($"    protected override IQueryable<Db.{e.EntityClass}> ApplyFilter(IQueryable<Db.{e.EntityClass}> query, {e.S}Filter filter)");
        sb.AppendLine("    {");
        if (e.SearchProps.Count > 0)
        {
            sb.AppendLine("        if (!string.IsNullOrWhiteSpace(filter.Q))");
            sb.AppendLine("        {");
            sb.AppendLine("            var q = filter.Q.Trim();");
            var conditions = e.SearchProps.Select(p => p.IsNullable ? $"(x.{p.Name} != null && x.{p.Name}.Contains(q))" : $"x.{p.Name}.Contains(q)");
            sb.AppendLine($"            query = query.Where(x => {string.Join("\n                || ", conditions)});");
            sb.AppendLine("        }");
            sb.AppendLine();
        }
        foreach (var p in e.IdFilterProps.Concat(e.FlagFilterProps))
        {
            sb.AppendLine($"        if (filter.{p.Name} is not null)");
            sb.AppendLine($"            query = query.Where(x => x.{p.Name} == filter.{p.Name}{(p.IsNullable ? "" : ".Value")});");
            sb.AppendLine();
        }
        if (e.DateFilterProp is { } d)
        {
            sb.AppendLine($"        if (filter.{d.Name}Desde is not null)");
            sb.AppendLine($"            query = query.Where(x => x.{d.Name} >= filter.{d.Name}Desde.Value);");
            sb.AppendLine();
            sb.AppendLine($"        if (filter.{d.Name}Hasta is not null)");
            sb.AppendLine("        {");
            if (d.Underlying == typeof(DateTime))
            {
                sb.AppendLine($"            var hasta = filter.{d.Name}Hasta.Value.Date.AddDays(1);");
                sb.AppendLine($"            query = query.Where(x => x.{d.Name} < hasta);");
            }
            else
            {
                sb.AppendLine($"            query = query.Where(x => x.{d.Name} <= filter.{d.Name}Hasta.Value);");
            }
            sb.AppendLine("        }");
            sb.AppendLine();
        }
        sb.AppendLine("        return query;");
        sb.AppendLine("    }");
        sb.AppendLine();
        var (col, desc) = e.DefaultOrder;
        sb.AppendLine($"    protected override IOrderedQueryable<Db.{e.EntityClass}> ApplyDefaultOrder(IQueryable<Db.{e.EntityClass}> query) =>");
        sb.AppendLine($"        query.{(desc ? "OrderByDescending" : "OrderBy")}(x => x.{col});");
        sb.AppendLine("}");
        return sb.ToString();
    }

