    public static string Controller(EntitySpec e)
    {
        var sb = new StringBuilder(Header);
        sb.AppendLine("using API.SERVICE.Models.Common;");
        sb.AppendLine($"using API.SERVICE.Models.{e.Module};");
        sb.AppendLine($"using API.SERVICE.UseCases.{e.Module};");
        sb.AppendLine("using Microsoft.AspNetCore.Authorization;");
        sb.AppendLine("using Microsoft.AspNetCore.Mvc;");
        sb.AppendLine();
        sb.AppendLine($"namespace API.Controllers.{e.Module};");
        sb.AppendLine();
        var access = e.IsWritable ? "" : " Solo lectura: las altas se hacen desde el flujo de negocio correspondiente.";
        sb.AppendLine($"/// <summary>{e.TableName}.{access}</summary>");
        sb.AppendLine("[ApiController]");
        sb.AppendLine("[Authorize]");
        sb.AppendLine("[Route(\"api/[controller]\")]");
        sb.AppendLine($"[Tags(\"{e.Module}\")]");
        sb.AppendLine("[Produces(\"application/json\")]");
        sb.AppendLine("[ProducesResponseType(typeof(ErrorCatchResponse), StatusCodes.Status401Unauthorized)]");
        sb.AppendLine($"public sealed partial class {e.S}Controller : ControllerBase");
        sb.AppendLine("{");

        var display = $"{e.S}Display";
        var route = $"{{id:{e.RouteConstraint}}}";
        var k = e.KeyType;

        sb.AppendLine($"    /// <summary>Listado paginado y filtrado.</summary>");
        sb.AppendLine("    [HttpGet]");
        sb.AppendLine($"    [ProducesResponseType(typeof(PagedResult<{display}>), StatusCodes.Status200OK)]");
        sb.AppendLine("    [ProducesResponseType(typeof(ValidationProblemDetails), StatusCodes.Status400BadRequest)]");
        sb.AppendLine($"    public async Task<ActionResult<PagedResult<{display}>>> GetList([FromQuery] {e.S}Filter filter, [FromServices] IGet{e.S}ListUseCase useCase, CancellationToken cancellationToken) =>");
        sb.AppendLine("        Ok(await useCase.ExecuteAsync(filter, cancellationToken));");

        if (e.HasLookup)
        {
            sb.AppendLine();
            sb.AppendLine("    /// <summary>Catálogo completo para combos (cacheado).</summary>");
            sb.AppendLine("    [HttpGet(\"lookup\")]");
            sb.AppendLine($"    [ProducesResponseType(typeof(IReadOnlyList<{display}>), StatusCodes.Status200OK)]");
            sb.AppendLine($"    public async Task<ActionResult<IReadOnlyList<{display}>>> GetLookup([FromServices] IGet{e.S}LookupUseCase useCase, CancellationToken cancellationToken) =>");
            sb.AppendLine("        Ok(await useCase.ExecuteAsync(cancellationToken));");
        }

        if (e.HasKey)
        {
            sb.AppendLine();
            sb.AppendLine("    /// <summary>Detalle por Id.</summary>");
            sb.AppendLine($"    [HttpGet(\"{route}\")]");
            sb.AppendLine($"    [ProducesResponseType(typeof({display}), StatusCodes.Status200OK)]");
            sb.AppendLine("    [ProducesResponseType(typeof(ErrorCatchResponse), StatusCodes.Status404NotFound)]");
            sb.AppendLine($"    public async Task<ActionResult<{display}>> GetById({k} id, [FromServices] IGet{e.S}ByIdUseCase useCase, CancellationToken cancellationToken) =>");
            sb.AppendLine("        Ok(await useCase.ExecuteAsync(id, cancellationToken));");
        }

        if (e.CanCreate)
        {
            sb.AppendLine();
            sb.AppendLine("    /// <summary>Alta.</summary>");
            sb.AppendLine("    [HttpPost]");
            sb.AppendLine($"    [ProducesResponseType(typeof({display}), StatusCodes.Status201Created)]");
            sb.AppendLine("    [ProducesResponseType(typeof(ValidationProblemDetails), StatusCodes.Status400BadRequest)]");
            sb.AppendLine("    [ProducesResponseType(typeof(ErrorCatchResponse), StatusCodes.Status409Conflict)]");
            sb.AppendLine($"    public async Task<ActionResult<{display}>> Create([FromBody] {e.S}Dto dto, [FromServices] ICreate{e.S}UseCase useCase, CancellationToken cancellationToken)");
            sb.AppendLine("    {");
            sb.AppendLine("        var created = await useCase.ExecuteAsync(dto, cancellationToken);");
            sb.AppendLine($"        return CreatedAtAction(nameof(GetById), new {{ id = created.{e.Key!.Name} }}, created);");
            sb.AppendLine("    }");
        }

        if (e.CanUpdate)
        {
            sb.AppendLine();
            sb.AppendLine("    /// <summary>Modificación.</summary>");
            sb.AppendLine($"    [HttpPut(\"{route}\")]");
            sb.AppendLine($"    [ProducesResponseType(typeof({display}), StatusCodes.Status200OK)]");
            sb.AppendLine("    [ProducesResponseType(typeof(ValidationProblemDetails), StatusCodes.Status400BadRequest)]");
            sb.AppendLine("    [ProducesResponseType(typeof(ErrorCatchResponse), StatusCodes.Status404NotFound)]");
            sb.AppendLine("    [ProducesResponseType(typeof(ErrorCatchResponse), StatusCodes.Status409Conflict)]");
            sb.AppendLine($"    public async Task<ActionResult<{display}>> Update({k} id, [FromBody] {e.S}Dto dto, [FromServices] IUpdate{e.S}UseCase useCase, CancellationToken cancellationToken) =>");
            sb.AppendLine("        Ok(await useCase.ExecuteAsync(id, dto, cancellationToken));");
        }

        if (e.CanDelete)
        {
            sb.AppendLine();
            sb.AppendLine("    /// <summary>Baja física (el ERP también borra estos registros).</summary>");
            sb.AppendLine($"    [HttpDelete(\"{route}\")]");
            sb.AppendLine("    [ProducesResponseType(StatusCodes.Status204NoContent)]");
            sb.AppendLine("    [ProducesResponseType(typeof(ErrorCatchResponse), StatusCodes.Status404NotFound)]");
            sb.AppendLine("    [ProducesResponseType(typeof(ErrorCatchResponse), StatusCodes.Status409Conflict)]");
            sb.AppendLine($"    public async Task<IActionResult> Delete({k} id, [FromServices] IDelete{e.S}UseCase useCase, CancellationToken cancellationToken)");
            sb.AppendLine("    {");
            sb.AppendLine("        await useCase.ExecuteAsync(id, cancellationToken);");
            sb.AppendLine("        return NoContent();");
            sb.AppendLine("    }");
        }

        sb.AppendLine("}");
        return sb.ToString();
    }

    public static string Registrations(IReadOnlyList<EntitySpec> entities)
    {
        var sb = new StringBuilder(Header);
        foreach (var module in entities.Select(e => e.Module).Distinct().Order())
        {
            sb.AppendLine($"using API.SERVICE.Interfaces.{module};");
            sb.AppendLine($"using API.SERVICE.Repositories.{module};");
            sb.AppendLine($"using API.SERVICE.UseCases.{module};");
        }
        sb.AppendLine("using Microsoft.Extensions.DependencyInjection;");
        sb.AppendLine();
        sb.AppendLine("namespace API.SERVICE.DependencyInjection;");
        sb.AppendLine();
        sb.AppendLine("public static partial class ServiceCollectionExtensions");
        sb.AppendLine("{");
        sb.AppendLine("    static partial void AddGeneratedServices(IServiceCollection services)");
        sb.AppendLine("    {");
        foreach (var group in entities.GroupBy(e => e.Module).OrderBy(g => g.Key))
        {
            sb.AppendLine($"        // {group.Key}");
            foreach (var e in group.OrderBy(x => x.S))
            {
                sb.AppendLine($"        services.AddScoped<I{e.S}Repository, {e.S}Repository>();");
                sb.AppendLine($"        services.AddScoped<IGet{e.S}ListUseCase, Get{e.S}ListUseCase>();");
                if (e.HasKey) sb.AppendLine($"        services.AddScoped<IGet{e.S}ByIdUseCase, Get{e.S}ByIdUseCase>();");
                if (e.HasLookup) sb.AppendLine($"        services.AddScoped<IGet{e.S}LookupUseCase, Get{e.S}LookupUseCase>();");
                if (e.CanCreate) sb.AppendLine($"        services.AddScoped<ICreate{e.S}UseCase, Create{e.S}UseCase>();");
                if (e.CanUpdate) sb.AppendLine($"        services.AddScoped<IUpdate{e.S}UseCase, Update{e.S}UseCase>();");
                if (e.CanDelete) sb.AppendLine($"        services.AddScoped<IDelete{e.S}UseCase, Delete{e.S}UseCase>();");
            }
            sb.AppendLine();
        }
        TrimBlankLine(sb);
        sb.AppendLine("    }");
        sb.AppendLine("}");
        return sb.ToString();
    }

    private static string RepositoryContract(EntitySpec e)
    {
        if (!e.HasKey)
            return $"global::API.SERVICE.Interfaces.IQueryRepository<Db.{e.EntityClass}, {e.S}Filter>";
        var kind = e.IsWritable ? "IRepository" : "IReadRepository";
        return $"global::API.SERVICE.Interfaces.{kind}<Db.{e.EntityClass}, {e.KeyType}, {e.S}Filter>";
    }

    /// <summary>Lectura de un campo del Dto (todo nullable) hacia el tipo de la entidad.</summary>
    private static string Read(PropSpec p, string source)
    {
        if (p.IsNullable)
            return $"{source}.{p.Name}";
        return p.IsValueType ? $"{source}.{p.Name}!.Value" : $"{source}.{p.Name}!";
    }

    private static void TrimBlankLine(StringBuilder sb)
    {
        var nl = Environment.NewLine;
        if (sb.Length >= nl.Length * 2 && sb.ToString(sb.Length - nl.Length * 2, nl.Length * 2) == nl + nl)
            sb.Length -= nl.Length;
    }
}
